const stems = ['甲','乙','丙','丁','戊','己','庚','辛','壬','癸'];
const branches = ['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥'];
const palaces = ['中宫','乾宫','兑宫','艮宫','离宫','坎宫','坤宫','震宫','巽宫'];
const gridOrder = ['巽宫','离宫','坤宫','震宫','中宫','兑宫','艮宫','坎宫','乾宫'];
const palaceShort = {'巽宫':'东南','离宫':'正南','坤宫':'西南','震宫':'正东','中宫':'中央','兑宫':'正西','艮宫':'东北','坎宫':'正北','乾宫':'西北'};
const guaByNumber = {1:'坎',2:'坤',3:'震',4:'巽',6:'乾',7:'兑',8:'艮',9:'离'};
const elementByGua = {'坎':'水','坤':'土','震':'木','巽':'木','乾':'金','兑':'金','艮':'土','离':'火'};
const starNames = {1:'一白官星',2:'二黑病符星',3:'三碧蚩尤星',4:'四绿文昌星',5:'五黄关煞星',6:'六白财星',7:'七赤贼星',8:'八白运星',9:'九紫喜星'};
const zodiac = ['鼠','牛','虎','兔','龙','蛇','马','羊','猴','鸡','狗','猪'];
const solarTermInfo=[0,21208,42467,63836,85337,107014,128867,150921,173149,195551,218072,240693,263343,285989,308563,331033,353350,375494,397447,419210,440795,462224,483532,504758];
const solarTermNames=['小寒','大寒','立春','雨水','惊蛰','春分','清明','谷雨','立夏','小满','芒种','夏至','小暑','大暑','立秋','处暑','白露','秋分','寒露','霜降','立冬','小雪','大雪','冬至'];
const monthNames=['正月','二月','三月','四月','五月','六月','七月','八月','九月','十月','冬月','腊月'];

function mod(n,m){return ((n%m)+m)%m}
function digitalRoot(n){while(n>9)n=String(n).split('').reduce((a,b)=>a+Number(b),0);return n}
function termDate(year,index){return new Date(31556925974.7*(year-1900)+solarTermInfo[index]*60000+Date.UTC(1900,0,6,2,5))}
function cnDate(d){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(d)}
function ganzhiYear(year){return stems[mod(year-4,10)]+branches[mod(year-4,12)]}
function effectiveYear(date){const y=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric'}).format(date));return date<termDate(y,2)?y-1:y}
function sexagenaryIndex(year){return mod(year-1984,60)}
function fly(values,reverse=false){const out={};palaces.forEach((p,i)=>out[p]=values[reverse?mod(-i,values.length):mod(i,values.length)]);return out}
function numberCycle(start){return Array.from({length:9},(_,i)=>mod(start-1+i,9)+1)}
function annualCenter(year){const s=digitalRoot([...String(year)].reduce((a,b)=>a+Number(b),0));return mod(10-s-1,9)+1}
function annualPlate(year){return fly(numberCycle(annualCenter(year)))}
function gridHTML(plate,marks={}){return `<div class="luoshu">${gridOrder.map(p=>{const v=plate[p];const cls=marks[v]||'';return `<div class="palace ${cls}">${v}<small>${p.replace('宫','')} · ${palaceShort[p]}</small></div>`}).join('')}</div>`}
function yearStemBranch(year){return {stem:stems[mod(year-4,10)],branch:branches[mod(year-4,12)]}}
function monthCenterFirst(branch){const i=branches.indexOf(branch);if([0,3,6,9].includes(i))return 8;if([1,4,7,10].includes(i))return 5;return 2}
function monthSegments(year){const {stem,branch}=yearStemBranch(year);const firstStem={甲:'丙',己:'丙',乙:'戊',庚:'戊',丙:'庚',辛:'庚',丁:'壬',壬:'壬',戊:'甲',癸:'甲'}[stem];const firstIdx=stems.indexOf(firstStem);const firstCenter=monthCenterFirst(branch);return monthNames.map((name,i)=>({name,branch:branches[mod(2+i,12)],stem:stems[mod(firstIdx+i,10)],start:termDate(year,2+i*2),end:i===11?termDate(year+1,2):termDate(year,4+i*2),center:mod(firstCenter-1-i,9)+1}));}
function activeMonth(year){const now=new Date();return monthSegments(year).findIndex(m=>now>=m.start&&now<m.end)}
function fiveTigerForStartStem(startStem){const start=stems.indexOf(startStem),hits=[];branches.slice(2).concat(branches.slice(0,2)).forEach((b,i)=>{const s=stems[mod(start+i,10)];if(s==='戊'||s==='己')hits.push({branch:b,stem:s})});return hits}
function firstMonthStem(yearStem){return {甲:'丙',己:'丙',乙:'戊',庚:'戊',丙:'庚',辛:'庚',丁:'壬',壬:'壬',戊:'甲',癸:'甲'}[yearStem]}
function branchPalace(branch){const idx=branches.indexOf(branch);if([11,0,1].includes(idx))return '坎宫';if([2,3,4].includes(idx))return '震/巽宫';if([5,6,7].includes(idx))return '离宫';return '兑/乾宫'}
function placeSequenceInPalaces(startValue,sequence,reverse=false){const start=sequence.indexOf(startValue),out={};palaces.forEach((p,i)=>out[p]=sequence[mod(start+(reverse?-i:i),sequence.length)]);return out}
function findPalace(map,value){return Object.keys(map).find(k=>map[k]===value)||'未找到'}

const nayin=['海中金','海中金','炉中火','炉中火','大林木','大林木','路旁土','路旁土','剑锋金','剑锋金','山头火','山头火','涧下水','涧下水','城头土','城头土','白蜡金','白蜡金','杨柳木','杨柳木','泉中水','泉中水','屋上土','屋上土','霹雳火','霹雳火','松柏木','松柏木','长流水','长流水','沙中金','沙中金','山下火','山下火','平地木','平地木','壁上土','壁上土','金箔金','金箔金','覆灯火','覆灯火','天河水','天河水','大驿土','大驿土','钗钏金','钗钏金','桑柘木','桑柘木','大溪水','大溪水','沙中土','沙中土','天上火','天上火','石榴木','石榴木','大海水','大海水'];
const lu={甲:'寅',乙:'卯',丙:'巳',戊:'巳',丁:'午',己:'午',庚:'申',辛:'酉',壬:'亥',癸:'子'};
const noble={甲:['未','丑'],乙:['申','子'],丙:['酉','亥'],丁:['亥','酉'],戊:['丑','未'],己:['子','申'],庚:['丑','未'],辛:['寅','午'],壬:['卯','巳'],癸:['巳','卯']};
const wenchang={甲:'巳',乙:'子',丙:'申',丁:'卯',戊:'亥',己:'卯',庚:'亥',辛:'未',壬:'寅',癸:'酉'};
function groupResult(branch,type){const i=branches.indexOf(branch);const water=[8,0,4],fire=[2,6,10],metal=[5,9,1],wood=[11,3,7];if(type==='horse'){if(water.includes(i))return'寅';if(fire.includes(i))return'申';if(metal.includes(i))return'亥';return'巳'}if(type==='peach'){if(water.includes(i))return'酉';if(fire.includes(i))return'卯';if(wood.includes(i))return'子';return'午'}if(type==='sansha'){if(water.includes(i))return['巳','午','未'];if(fire.includes(i))return['亥','子','丑'];if(metal.includes(i))return['寅','卯','辰'];return['申','酉','戌']}}
function mingGua(year,gender){const s=digitalRoot([...String(year)].reduce((a,b)=>a+Number(b),0));let n=gender==='male'?mod(10-s-1,9)+1:mod(s+4-1,9)+1;if(n===5)n=gender==='male'?2:8;return {number:n,gua:guaByNumber[n],element:elementByGua[guaByNumber[n]],group:[1,3,4,9].includes(n)?'东四命':'西四命'};}

function personalReport(date,gender){const year=effectiveYear(date),{stem,branch}=yearStemBranch(year),mg=mingGua(year,gender),ss=groupResult(branch,'sansha'),ng=noble[stem];return {year,gz:stem+branch,stem,branch,zodiac:zodiac[branches.indexOf(branch)],ming:mg,nayin:nayin[sexagenaryIndex(year)],sansha:ss,lu:lu[stem],horse:groupResult(branch,'horse'),peach:groupResult(branch,'peach'),yangNoble:ng[0],yinNoble:ng[1],wenchang:wenchang[stem]};}

function renderPersonal(data){document.querySelector('#personalResults').innerHTML=`
  <div class="result-block result-hero"><div class="section-label">个人总览</div><h3>${data.gz} · ${data.ming.gua}命</h3><p>规则年 ${data.year} · 属${data.zodiac} · ${data.ming.element}卦 · ${data.ming.group}</p></div>
  <div class="result-block"><div class="stat-grid">
    ${[['命卦',`${data.ming.gua}卦 · ${data.ming.number}`,data.ming.group],['纳音',data.nayin,'出生年干支'],['人命三煞',data.sansha.join('、')+'山','判断住宅时需结合坐山'],['禄位',data.lu+'山','由出生年天干'],['马位',data.horse+'山','由出生年地支'],['正桃花',data.peach+'山','其余子午卯酉为偏桃花'],['阳贵人',data.yangNoble+'山','冬至至夏至用事'],['阴贵人',data.yinNoble+'山','夏至至冬至用事'],['本命文昌',data.wenchang+'山','笔记列为参考项']].map(x=>`<div class="stat"><small>${x[0]}</small><b>${x[1]}</b><em>${x[2]}</em></div>`).join('')}
  </div><p class="rule-note">出生年以立春为界。本页给出个人固定方位；它们还没有与具体住宅的财位、非位及流年凶星叠加。</p></div>`}

function moduleHeader(title,desc,tag,body){return `<div class="module-title"><div><h3>${title}</h3><p>${desc}</p></div><span class="tag">${tag}</span></div>${body}`}
function renderAnnual(year){const plate=annualPlate(year),center=annualCenter(year),four=findPalace(plate,4);return moduleHeader(`${ganzhiYear(year)}流年九星盘`,`四绿文昌星属于本盘结果，不另设计算模块。`,`${year} · ${center}入中`, `<div class="annual-layout">${gridHTML(plate,{4:'mark',2:'bad',5:'bad'})}<div class="detail-list"><div class="detail-item"><small>值年飞星</small><b>${starNames[center]}</b></div><div class="detail-item"><small>四绿文昌星</small><b>${four} · ${palaceShort[four]}</b></div><div class="detail-item"><small>五黄关煞星</small><b>${findPalace(plate,5)}</b></div><div class="detail-item"><small>二黑病符星</small><b>${findPalace(plate,2)}</b></div></div></div><p class="rule-note">年份数字求和后按男命卦同法取值年星，五入中时不寄卦；入中后按洛书顺飞。</p>`)}
function renderMonths(year,mode){const months=monthSegments(year),active=activeMonth(year);if(mode==='monthly'){return moduleHeader(`${ganzhiYear(year)}全年流月盘`,`从立春到下一年立春，一次列出十二个节气月。`,`${year}年`, `<div class="month-cards">${months.map((m,i)=>`<article class="month-card ${i===active?'current':''}"><h4>${m.name} · ${m.stem}${m.branch}</h4><p>${cnDate(m.start)} — ${cnDate(m.end)}</p><strong>${m.center} 入中 · 四绿在 ${findPalace(fly(numberCycle(m.center)),4).replace('宫','')}</strong></article>`).join('')}</div><p class="rule-note">正月值月星由年支分组确定，之后每月递减一位，遇零取九。月份以节气划分。</p>`)}
return moduleHeader(`${ganzhiYear(year)}全年月五虎`,`每月分别排出戊、己所到的山位。`,`${year}年`, `<table class="year-table"><thead><tr><th>月份</th><th>月干支</th><th>有效时间</th><th>月五虎山位</th></tr></thead><tbody>${months.map((m,i)=>{const hits=fiveTigerForStartStem(m.stem);return `<tr class="${i===active?'current':''}"><td>${m.name}</td><td>${m.stem}${m.branch}</td><td>${cnDate(m.start)} — ${cnDate(m.end)}</td><td>${hits.map(h=>h.branch).join('、')}</td></tr>`}).join('')}</tbody></table><p class="rule-note">以当月天干从寅位起布十天干，戊、己落到的地支即为当月五虎杀。</p>`)}
function renderYearTiger(year){const {stem}=yearStemBranch(year),start=firstMonthStem(stem),hits=fiveTigerForStartStem(start);return moduleHeader(`${ganzhiYear(year)}年五虎杀`,`由该年正月天干起布，查找戊、己所在山位。`,`正月${start}寅`, `<div class="mountain-row">${hits.map(h=>`<span class="mountain">${h.branch}<small>${h.stem}</small></span>`).join('')}</div><p class="rule-note">每组年五虎从上一年大雪提前出现，持续至下一年立春。因此大雪至立春期间，两年的五虎杀同时存在。</p>`)}
function renderEarth(year){const {branch}=yearStemBranch(year),opp=branches[mod(branches.indexOf(branch)+6,12)],ss=groupResult(branch,'sansha'),toward=ss.map(b=>branches[mod(branches.indexOf(b)+6,12)]);return moduleHeader(`${ganzhiYear(year)}太岁、岁破与年三煞`,`这里计算通用山位；判断住宅是否犯煞仍需坐山。`,`${year}年`, `<div class="detail-list"><div class="detail-item"><small>太岁</small><b>${branch}山</b></div><div class="detail-item"><small>岁破</small><b>${opp}山</b></div><div class="detail-item"><small>三煞山</small><b>${ss.join('、')}</b></div><div class="detail-item"><small>向煞</small><b>${toward.join('、')}</b></div></div><p class="rule-note">夹煞位于三煞地支之间所夹的天干山，具体罗盘标注在完整二十四山视图中呈现。</p>`)}
function renderHidden(year){const months=monthSegments(year),active=activeMonth(year);return moduleHeader(`${ganzhiYear(year)}全年暗建杀`,`由每月值月星返回洛书原位确定。`,`${year}年`, `<table class="year-table"><thead><tr><th>月份</th><th>月干支</th><th>值月星</th><th>暗建杀</th></tr></thead><tbody>${months.map((m,i)=>`<tr class="${i===active?'current':''}"><td>${m.name}</td><td>${m.stem}${m.branch}</td><td>${m.center} 入中</td><td>${m.center===5?'无':guaByNumber[m.center]+'宫'}</td></tr>`).join('')}</tbody></table><p class="rule-note">值月飞星五居中宫时没有暗建杀；其余月份取值月星在洛书中的原始宫位。</p>`)}
function renderNoble(year){const {stem,branch}=yearStemBranch(year),[yang,yin]=noble[stem],forward=placeSequenceInPalaces(branch,branches,false),reverse=placeSequenceInPalaces(branch,branches,true),yp=findPalace(forward,yang),ip=findPalace(reverse,yin);return moduleHeader(`${ganzhiYear(year)}天乙贵人`,`阳贵顺飞、阴贵逆飞；用事切换点为冬至和夏至。`,`${stem}年`, `<div class="detail-list"><div class="detail-item"><small>阳贵人</small><b>${yang} · ${yp}</b></div><div class="detail-item"><small>阴贵人</small><b>${yin} · ${ip}</b></div><div class="detail-item"><small>阳贵用事</small><b>上一年冬至至本年夏至</b></div><div class="detail-item"><small>阴贵用事</small><b>本年夏至至本年冬至</b></div></div><p class="rule-note">若贵人地支本身所在的二十四山与飞布后的卦宫一致，笔记称为“还家贵人”。</p>`)}
function renderWenchang(year){const {stem,branch}=yearStemBranch(year),target=wenchang[stem],map=placeSequenceInPalaces(branch,branches,false),p=findPalace(map,target);return moduleHeader(`${ganzhiYear(year)}流年文昌`,`这是独立公式，与流年盘中的四绿文昌星不同。`,`${stem} → ${target}`, `<div class="annual-layout"><div class="mountain-row"><span class="mountain gold">${target}</span></div><div class="detail-list"><div class="detail-item"><small>流年文昌地支</small><b>${target}</b></div><div class="detail-item"><small>飞布所在</small><b>${p==='中宫'?'中宫，本年无可用流年文昌':p+' · '+palaceShort[p]}</b></div></div></div><p class="rule-note">先将当年地支入中宫顺飞，再以当年天干查文昌地支；该地支飞到的宫位就是流年文昌。</p>`)}
function renderFame(year){const {stem,branch}=yearStemBranch(year),earthBranch=branches[mod(branches.indexOf(branch)+3,12)],earthPalace=branchPalace(earthBranch),stemMap=placeSequenceInPalaces(stem,stems,false),three={壬:findPalace(stemMap,'壬'),癸:findPalace(stemMap,'癸'),辛:findPalace(stemMap,'辛')},match=Object.entries(three).find(([,p])=>p.replace('宫','')===earthPalace.replace('宫',''));return moduleHeader(`${ganzhiYear(year)}利名星`,`土曲星与地三奇同宫时，该宫才形成利名星。`,match?'本年形成':'本年未形成', `<div class="detail-list"><div class="detail-item"><small>土曲星</small><b>${earthBranch}山 · ${earthPalace}</b></div><div class="detail-item"><small>地三奇</small><b>壬 ${three.壬} · 癸 ${three.癸} · 辛 ${three.辛}</b></div><div class="detail-item"><small>计算结论</small><b>${match?match[1]+'为利名星':'土曲星未与地三奇重合'}</b></div></div><p class="rule-note">十二建除从年支起“建”顺排，找到“平”为土曲星；再将年干入中顺飞，查壬、癸、辛三奇是否重合。</p>`)}

let activeModule='annual';
function renderModule(){const year=Number(document.querySelector('#queryYear').value);const map={annual:renderAnnual,monthly:y=>renderMonths(y,'monthly'),yearTiger:renderYearTiger,monthTiger:y=>renderMonths(y,'monthTiger'),earth:renderEarth,hidden:renderHidden,noble:renderNoble,wenchang:renderWenchang,fame:renderFame};document.querySelector('#moduleResult').innerHTML=map[activeModule](year)}

document.querySelectorAll('.mode-tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.mode-tab').forEach(x=>x.classList.toggle('active',x===btn));document.querySelectorAll('.mode-panel').forEach(x=>x.classList.toggle('active',x.id===btn.dataset.mode));}));
document.querySelectorAll('.module-tab').forEach(btn=>btn.addEventListener('click',()=>{activeModule=btn.dataset.module;document.querySelectorAll('.module-tab').forEach(x=>x.classList.toggle('active',x===btn));renderModule()}));
document.querySelector('#personalForm').addEventListener('submit',e=>{e.preventDefault();const d=document.querySelector('#birthDate').value,t=document.querySelector('#birthTime').value||'12:00',g=document.querySelector('input[name=gender]:checked').value;renderPersonal(personalReport(new Date(`${d}T${t}:00+08:00`),g))});
const select=document.querySelector('#queryYear'),current=effectiveYear(new Date());for(let y=current-20;y<=current+20;y++){const o=document.createElement('option');o.value=y;o.textContent=`${y} · ${ganzhiYear(y)}年`;o.selected=y===current;select.append(o)}select.addEventListener('change',renderModule);
document.querySelector('#todayChip').textContent=`今日 · ${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric'}).format(new Date())}`;
document.querySelector('#personalForm').requestSubmit();renderModule();

if(document.modelContext?.registerTool){
  const register=(tool)=>Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});
  register({name:'calculate_personal_liqi',title:'计算个人理气',description:'根据出生日期、时间和性别更新页面并返回个人命卦、纳音、三煞、禄马、桃花、贵人和文昌。',inputSchema:{type:'object',properties:{birthDate:{type:'string',description:'YYYY-MM-DD'},birthTime:{type:'string',description:'HH:mm'},gender:{type:'string',enum:['male','female']}},required:['birthDate','gender'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!/^\d{4}-\d{2}-\d{2}$/.test(input.birthDate))throw new Error('出生日期格式应为 YYYY-MM-DD');const time=input.birthTime||'12:00';const data=personalReport(new Date(`${input.birthDate}T${time}:00+08:00`),input.gender);document.querySelector('#birthDate').value=input.birthDate;document.querySelector('#birthTime').value=time;document.querySelector(`input[name=gender][value=${input.gender}]`).checked=true;renderPersonal(data);return data;}});
  register({name:'show_general_calculation',title:'查看通用计算',description:'按干支年切换并展示一个独立通用计算模块。',inputSchema:{type:'object',properties:{year:{type:'integer',minimum:1901,maximum:2099},module:{type:'string',enum:['annual','monthly','yearTiger','monthTiger','earth','hidden','noble','wenchang','fame']}},required:['year','module'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!document.querySelector(`#queryYear option[value="${input.year}"]`)){const o=document.createElement('option');o.value=input.year;o.textContent=`${input.year} · ${ganzhiYear(input.year)}年`;select.append(o)}select.value=String(input.year);activeModule=input.module;document.querySelectorAll('.module-tab').forEach(x=>x.classList.toggle('active',x.dataset.module===activeModule));document.querySelectorAll('.mode-tab').forEach(x=>x.classList.toggle('active',x.dataset.mode==='general'));document.querySelectorAll('.mode-panel').forEach(x=>x.classList.toggle('active',x.id==='general'));renderModule();return {year:input.year,module:input.module,displayed:true};}});
}
